#pragma once
#include "animation_quaternion.hpp"
// Native adapter for XanimeCore normalized track accumulation; frozen/previous-pose stages pending.
inline ModelRig blendAnimationTracks(const ModelRig& fallback,const std::vector<ModelRig>& tracks,const std::vector<float>& weights){
 assetCheck(tracks.size()==weights.size()&&tracks.size()<=4,"Invalid animation track count");float total=0;for(size_t i=0;i<tracks.size();++i){assetCheck(std::isfinite(weights[i])&&weights[i]>=0&&tracks[i].joints.size()==fallback.joints.size()&&tracks[i].matrixMode==fallback.matrixMode,"Invalid animation track weight/rig");total+=weights[i];for(size_t j=0;j<fallback.joints.size();++j)assetCheck(tracks[i].joints[j].parent==fallback.joints[j].parent&&tracks[i].joints[j].scaleCompensate==fallback.joints[j].scaleCompensate,"Animation track hierarchy mismatch");}assetCheck(std::isfinite(total),"Animation weights overflow");if(total==0)return fallback;
 auto result=fallback;for(size_t j=0;j<result.joints.size();++j){auto& out=result.joints[j];out.scale={0,0,0};out.translation={0,0,0};NativeAnimationQuaternion rotation;float accumulated=0;for(size_t i=0;i<tracks.size();++i){if(weights[i]==0)continue;float weight=weights[i]/total;auto& joint=tracks[i].joints[j];auto q=joint.quaternion;auto track=joint.useQuaternion?NativeAnimationQuaternion{q[0],q[1],q[2],q[3]}:nativeAnimationQuaternion(joint.rotation[0],joint.rotation[1],joint.rotation[2]);for(size_t axis=0;axis<3;++axis){assetCheck(std::isfinite(joint.scale[axis])&&std::isfinite(joint.translation[axis]),"Invalid animation joint SRT");out.scale[axis]+=joint.scale[axis]*weight;out.translation[axis]+=joint.translation[axis]*weight;}accumulated+=weight;rotation=lerpAnimationQuaternion(rotation,track,weight/accumulated);}out.useQuaternion=true;out.quaternion={rotation.x,rotation.y,rotation.z,rotation.w};}return result;
}
inline void animationTrackBlendTests(){ModelRig a;a.joints.resize(1);a.joints[0].scale={1,1,1};auto b=a;b.joints[0].scale={3,3,3};b.joints[0].translation={10,20,30};b.joints[0].rotation={0,0,16384};auto mixed=blendAnimationTracks(a,{a,b},{1,3});assetCheck(mixed.joints[0].scale[0]==2.5f&&mixed.joints[0].translation[1]==15&&mixed.joints[0].useQuaternion,"Weighted animation SRT blend failed");auto matrix=jointRotationTranslation(mixed.joints[0]);auto expected=animationQuaternionMatrix(lerpAnimationQuaternion({},nativeAnimationQuaternion(0,0,16384),.75f));for(size_t k=0;k<12;++k)if(k%4!=3)assetCheck(std::abs(matrix[k]-expected[k])<1e-5,"Blended quaternion did not reach skinning");auto zero=blendAnimationTracks(a,{b},{0});assetCheck(!zero.joints[0].useQuaternion&&zero.joints[0].rotation==a.joints[0].rotation,"Zero-weight fallback changed pose");bool rejected=false;try{blendAnimationTracks(a,{b},{-1});}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Negative track weight accepted");b.joints[0].parent=0;rejected=false;try{blendAnimationTracks(a,{b},{1});}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Mismatched track hierarchy accepted");}

// XanimeCore::calcBlend frozen stage followed by previous-pose stage.
inline ModelRig blendAnimationPoseStages(const ModelRig& current,const ModelRig& frozen,const ModelRig& previous,float frozenBlend,float previousBlend){
 assetCheck(std::isfinite(frozenBlend)&&frozenBlend>=0&&frozenBlend<=1&&std::isfinite(previousBlend)&&previousBlend>=0&&previousBlend<=1,"Invalid animation pose stage blend");
 auto result=current;if(frozenBlend<1)result=blendAnimationTracks(current,{frozen,current},{1-frozenBlend,frozenBlend});if(previousBlend!=1)result=blendAnimationTracks(current,{previous,result},{1-previousBlend,previousBlend});return result;
}
inline void animationPoseStageTests(){
 ModelRig base;base.joints.resize(1);base.joints[0].scale={1,1,1};auto current=base,frozen=base,previous=base;current.joints[0].translation={20,0,0};frozen.joints[0].translation={4,0,0};previous.joints[0].translation={-8,0,0};
 auto result=blendAnimationPoseStages(current,frozen,previous,.25f,.5f);assetCheck(result.joints[0].translation[0]==0,"Frozen/previous animation stage order mismatch");auto untouched=blendAnimationPoseStages(current,frozen,previous,1,1);assetCheck(!untouched.joints[0].useQuaternion&&untouched.joints[0].translation==current.joints[0].translation,"Bypassed animation stage changed pose");auto endpoint=blendAnimationPoseStages(current,frozen,previous,0,1);assetCheck(endpoint.joints[0].translation==frozen.joints[0].translation,"Frozen pose endpoint mismatch");bool rejected=false;try{blendAnimationPoseStages(current,frozen,previous,-1,1);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Invalid frozen-stage blend accepted");
}

// Native tick-owned pose history; timing is explicit, not the full XanimePlayer lifecycle.
class NativeAnimationPoseHistory {
 ModelRig frozen,previous,current;unsigned duration=0,elapsed=0;float previousBlend=1;
public:
 explicit NativeAnimationPoseHistory(const ModelRig& initial):frozen(initial),previous(initial),current(initial){}
 void begin(unsigned ticks,float smoothing=1){assetCheck(ticks<=600&&std::isfinite(smoothing)&&smoothing>=0&&smoothing<=1,"Invalid pose transition timing");frozen=current;duration=ticks;elapsed=0;previousBlend=smoothing;}
 void advanceRatio(const ModelRig& raw,float ratio){auto result=blendAnimationPoseStages(raw,frozen,previous,ratio,previousBlend);previous=result;current=std::move(result);}
 void advance(const ModelRig& raw){unsigned next=elapsed<duration?elapsed+1:elapsed;float blend=duration?float(next)/duration:1;auto result=blendAnimationPoseStages(raw,frozen,previous,blend,previousBlend);previous=result;current=std::move(result);elapsed=next;}
 const ModelRig& pose()const{return current;}
 unsigned step()const{return elapsed;}
};
inline void animationPoseHistoryTests(){ModelRig base;base.joints.resize(1);base.joints[0].scale={1,1,1};auto target=base;target.joints[0].translation={12,0,0};NativeAnimationPoseHistory history(base);history.begin(3);history.advance(target);assetCheck(std::abs(history.pose().joints[0].translation[0]-4)<1e-5,"Pose transition first step mismatch");history.advance(target);assetCheck(std::abs(history.pose().joints[0].translation[0]-8)<1e-5,"Pose transition second step mismatch");history.begin(2);history.advance(base);assetCheck(std::abs(history.pose().joints[0].translation[0]-4)<1e-5,"Interrupted pose transition discontinuity");history.advance(base);assetCheck(history.pose().joints[0].translation[0]==0&&history.step()==2,"Pose transition endpoint mismatch");history.begin(0,.5f);history.advance(target);assetCheck(history.pose().joints[0].translation[0]==6,"Persistent previous-pose smoothing mismatch");}

// Native scalar adapter for XanimePlayer::changeInterpoleFrame/updateInterpoleRatio.
struct NativeAnimationInterpolation {
 float ratio=1;int remaining=0;
 void update(float playbackRate,uint8_t attribute){assetCheck(std::isfinite(playbackRate)&&attribute<=4,"Invalid interpolation playback context");if(playbackRate!=0||attribute==1){if(remaining!=0){ratio+=(1-ratio)/remaining;--remaining;}else ratio=1;}else{ratio=1;remaining=0;}}
 void change(int frames,float playbackRate,uint8_t attribute){assetCheck(frames>=0&&frames<=600,"Invalid interpolation frame count");auto next=*this;next.remaining=frames;next.ratio=frames==0?1:0;if(frames)next.update(playbackRate,attribute);*this=next;}
};
inline void animationInterpolationTests(){NativeAnimationInterpolation state;state.change(4,1,2);assetCheck(state.ratio==.25f&&state.remaining==3,"Initial original interpolation update missing");state.update(1,2);assetCheck(state.ratio==.5f&&state.remaining==2,"Original interpolation countdown mismatch");state.update(1,2);state.update(1,2);assetCheck(state.ratio==1&&state.remaining==0,"Original interpolation completion mismatch");state.change(8,0,2);assetCheck(state.ratio==1&&state.remaining==0,"Stopped playback did not complete interpolation");state.change(4,0,1);assetCheck(state.ratio==.25f&&state.remaining==3,"Attribute-one stopped interpolation mismatch");state.change(0,1,2);assetCheck(state.ratio==1&&state.remaining==0,"Zero interpolation duration mismatch");bool rejected=false;try{state.change(-1,1,2);}catch(const std::exception&){rejected=true;}assetCheck(rejected&&state.ratio==1&&state.remaining==0,"Invalid interpolation changed state");}

